"use client";

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import type { Product, ProductStatus } from "@atelier/shared";
import { createProductSchema, updateProductSchema } from "@atelier/shared";
import { mockProducts } from "./products.mock";
import { useAuth } from "@/contexts/AuthContext";

// モックデータをクライアント状態で管理
let productsStore: Product[] = [...mockProducts];

async function fetchProducts(): Promise<Product[]> {
  // モックデータを返す
  return Promise.resolve(productsStore);
}

async function fetchProduct(id: string): Promise<Product> {
  // モックデータから取得
  const product = productsStore.find((p) => p.id === id);
  if (!product) {
    throw new Error("Product not found");
  }
  return Promise.resolve(product);
}

// UUIDを生成する関数（ブラウザ環境でも動作）
function generateUUID(): string {
  if (typeof crypto !== "undefined" && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  // フォールバック: 簡易UUID生成
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === "x" ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

async function addProduct(
  product: Omit<Product, "id" | "createdAt" | "updatedAt">
): Promise<Product> {
  // モックデータに追加
  const validated = createProductSchema.parse(product);
  const newProduct: Product = {
    ...validated,
    id: generateUUID(),
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
  productsStore = [...productsStore, newProduct];
  return Promise.resolve(newProduct);
}

async function updateProduct(
  id: string,
  updates: Partial<Omit<Product, "id" | "createdAt" | "updatedAt">>
): Promise<Product> {
  // モックデータを更新
  const validated = updateProductSchema.parse(updates);
  const productIndex = productsStore.findIndex((p) => p.id === id);
  if (productIndex === -1) {
    throw new Error("Product not found");
  }
  const updatedProduct: Product = {
    ...productsStore[productIndex],
    ...validated,
    updatedAt: new Date().toISOString(),
  };
  productsStore = [
    ...productsStore.slice(0, productIndex),
    updatedProduct,
    ...productsStore.slice(productIndex + 1),
  ];
  return Promise.resolve(updatedProduct);
}

export function useProducts() {
  const { shopId } = useAuth();
  return useQuery({
    queryKey: ["products", shopId],
    queryFn: fetchProducts,
  });
}

export function useProduct(id: string) {
  return useQuery({
    queryKey: ["product", id],
    queryFn: () => fetchProduct(id),
    enabled: !!id,
  });
}

export function useAddProduct() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: addProduct,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["products"] });
    },
  });
}

export function useUpdateProduct() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ id, updates }: { id: string; updates: Parameters<typeof updateProduct>[1] }) =>
      updateProduct(id, updates),
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["products"] });
      queryClient.invalidateQueries({ queryKey: ["product", variables.id] });
    },
  });
}

export function useUpdateProductStatus() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ id, status }: { id: string; status: ProductStatus }) =>
      updateProduct(id, { status }),
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["products"] });
      queryClient.invalidateQueries({ queryKey: ["product", variables.id] });
    },
  });
}
